from torch.utils.data import Dataset


class TransformersSeqPairDataset(Dataset):
    def __init__(self, **kwargs):
        self.valid_attrs = []
        self.kwargs = kwargs
        for attr, values in kwargs.items():
            self.valid_attrs.append(attr)
            setattr(self, attr, values)

